query:
mutation CreateOneAttachment($input: AttachmentCreateInput!) {
  createAttachment(data: $input) {
    __typename
    createdAt
    createdBy {
      source
      workspaceMemberId
      name
      context {
        provider
        applicationId
        __typename
      }
      __typename
    }
    deletedAt
    file {
      fileId
      label
      extension
      url
      __typename
    }
    fileCategory
    fullPath
    id
    name
    position
    targetAgentChatThread {
      __typename
      id
      title
    }
    targetAgentChatThreadId
    targetCompany {
      __typename
      domainName {
        primaryLinkUrl
        primaryLinkLabel
        secondaryLinks {
          label
          url
          __typename
        }
        __typename
      }
      id
      name
    }
    targetCompanyId
    targetDashboard {
      __typename
      id
      title
    }
    targetDashboardId
    targetInitiative {
      __typename
      id
      name
    }
    targetInitiativeId
    targetMessage {
      __typename
      id
      subject
    }
    targetMessageId
    targetNote {
      __typename
      id
      title
    }
    targetNoteId
    targetOpportunity {
      __typename
      id
      name
    }
    targetOpportunityId
    targetPerson {
      __typename
      avatarFile {
        fileId
        label
        extension
        url
        __typename
      }
      id
      name {
        firstName
        lastName
        __typename
      }
    }
    targetPersonId
    targetTask {
      __typename
      id
      title
    }
    targetTaskId
    targetWorkflow {
      __typename
      id
      name
    }
    targetWorkflowId
    updatedAt
    updatedBy {
      source
      workspaceMemberId
      name
      context {
        provider
        applicationId
        __typename
      }
      __typename
    }
  }
}
